package com.airesumebuilder.feature.audit.repository;
import com.airesumebuilder.feature.audit.service.AuditService.AuditEntry;import java.sql.*;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AuditRepository{private final JdbcTemplate jdbc;public AuditRepository(JdbcTemplate j){jdbc=j;}public void append(Long userId,String type,long entityId,String action,String beforeState,String afterState){jdbc.update("INSERT INTO audit_logs(user_id,entity_type,entity_id,action,before_state,after_state,created_at) VALUES (?,?,?,?,CAST(? AS JSON),CAST(? AS JSON),NOW(6))",userId,type,entityId,action,beforeState,afterState);}public List<AuditEntry>listForUser(String email,int limit,int offset){return jdbc.query("SELECT a.id,a.entity_type,a.entity_id,a.action,a.before_state,a.after_state,a.ip_address,a.created_at FROM audit_logs a JOIN users u ON u.id=a.user_id WHERE u.email=? ORDER BY a.created_at DESC LIMIT ? OFFSET ?",this::map,email,limit,offset);}public long countForUser(String email){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs a JOIN users u ON u.id=a.user_id WHERE u.email=?",Long.class,email);return n==null?0:n;}public List<AuditEntry>listAll(int limit,int offset){return jdbc.query("SELECT id,entity_type,entity_id,action,before_state,after_state,ip_address,created_at FROM audit_logs ORDER BY created_at DESC LIMIT ? OFFSET ?",this::map,limit,offset);}public long countAll(){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs",Long.class);return n==null?0:n;}private AuditEntry map(ResultSet r,int n)throws SQLException{return new AuditEntry(r.getLong("id"),r.getString("entity_type"),r.getLong("entity_id"),r.getString("action"),r.getString("before_state"),r.getString("after_state"),r.getString("ip_address"),r.getTimestamp("created_at").toInstant());}}
